import java.util.Scanner;

public class MatrixExponentiation {
    static final long MOD = 1000000007;
    static int K_input;
    static long N_input;
    static MatrixStruct identityMatrix = new MatrixStruct();
    static MatrixStruct[] matricesSet = new MatrixStruct[70];
    static MatrixStruct[] prefixMatrices = new MatrixStruct[70];
    static MatrixStruct[] suffixMatrices = new MatrixStruct[70];
    static MatrixStruct finalMatrix = new MatrixStruct();

    static class MatrixStruct {
        int[][] matrix = new int[33][33];
    }

    static void printMatrix(MatrixStruct mat) {
        for (int i = 0; i <= K_input; i++) {
            for (int j = 0; j <= K_input; j++)
                System.out.print(mat.matrix[i][j] + " ");
            System.out.println();
        }
        System.out.println();
    }

    static MatrixStruct multiply(MatrixStruct A, MatrixStruct B) {
        MatrixStruct C = new MatrixStruct();
        // Initialize C as identity matrix
        for (int i = 0; i <= K_input; i++) {
            for (int j = 0; j <= K_input; j++) {
                C.matrix[i][j] = 0;
            }
        }
        for (int i = 0; i <= K_input; i++) {
            C.matrix[i][i] = 1;
        }
        for (int k = 0; k <= K_input; k++) {
            for (int i = 0; i <= K_input; i++) {
                for (int j = 0; j <= K_input; j++) {
                    long val = ((long) A.matrix[i][k] * B.matrix[k][j]) % MOD;
                    C.matrix[i][j] = (int) ((C.matrix[i][j] + val) % MOD);
                }
            }
        }
        return C;
    }

    static void preparePrefixSuffix() {
        int i;
        prefixMatrices[0] = matricesSet[0];
        for (i = 1; i < K_input; i++)
            prefixMatrices[i] = multiply(prefixMatrices[i - 1], matricesSet[i]);
        suffixMatrices[K_input - 1] = matricesSet[K_input - 1];
        for (i = K_input - 2; i >= 0; i--)
            suffixMatrices[i] = multiply(matricesSet[i], suffixMatrices[i + 1]);
        matricesSet[0] = suffixMatrices[0];
        for (i = 1; i < K_input; i++)
            matricesSet[i] = multiply(suffixMatrices[i], prefixMatrices[i - 1]);
    }

    static void execute() {
        Scanner sc = new Scanner(System.in);
        N_input = sc.nextLong();
        K_input = sc.nextInt();

        // Initialize identityMatrix
        for (int i = 0; i <= K_input; i++) {
            for (int j = 0; j <= K_input; j++) {
                identityMatrix.matrix[i][j] = 0;
            }
            identityMatrix.matrix[i][i] = 1;
        }

        finalMatrix = new MatrixStruct();
        // Initialize finalMatrix
        for (int i = 0; i <= K_input; i++) {
            for (int j = 0; j <= K_input; j++) {
                finalMatrix.matrix[i][j] = 0;
            }
        }
        for (int i = 0; i < K_input; i++) {
            matricesSet[i] = new MatrixStruct();
            for (int j = 0; j <= K_input; j++) {
                matricesSet[i].matrix[j][j] = 1;
                matricesSet[i].matrix[j][i] = 1;
            }
            finalMatrix.matrix[i][i] = 1;
        }
        finalMatrix.matrix[K_input][K_input] = 1;

        while (N_input > 0) {
            long r = N_input % K_input;
            if (r != 0) {
                long pos = 0, tmp = N_input;
                while (tmp != 0) {
                    tmp /= K_input;
                    pos = (pos + tmp) % K_input;
                }
                for (long i = r - 1; i >= 0; i--) {
                    finalMatrix = multiply(matricesSet[(int)((pos + i) % K_input)], finalMatrix);
                }
            }
            preparePrefixSuffix();
            N_input /= K_input;
        }
        int ans = 1;
        for (int i = 0; i < K_input; i++) {
            ans = (ans + finalMatrix.matrix[K_input][i]) % (int)MOD;
        }
        System.out.println(ans);
        sc.close();
    }

    public static void main(String[] args) {
        execute();
    }
}

